SELECT (EXISTS (SELECT 1 FROM crypto_ai.trade_signal p WHERE p.symbol = s.symbol AND p.interval_code = '1m' AND p.decision = 'STRONG_SELL' AND p.candle_open_time BETWEEN s.candle_open_time - INTERVAL 3 MINUTE AND s.candle_open_time - INTERVAL 1 MINUTE)) AS after_strong_sell, COUNT(*) AS n, SUM(pp.realized_pnl < 0) AS losers, SUM(pp.status = 'STOPPED') AS stopped, SUM(pp.realized_pnl) AS net_pnl, AVG(pp.realized_pnl / NULLIF(pp.entry_price * pp.quantity, 0) * 100) AS avg_pnl_pct FROM crypto_ai.paper_position pp JOIN crypto_ai.trade_signal s ON s.id = pp.signal_id WHERE pp.status IN ('CLOSED','STOPPED') AND s.interval_code = '1m' GROUP BY after_strong_sell LIMIT 5